/**
 * AK47网址导航 子页面顶部实时时钟脚本 (已去混淆 & 移除域名锁)
 */
(function () {
  var time = document.querySelector("#time");
  if (!time) return;
  function updateSubClock() {
    var now = new Date();
    var h = now.getHours();
    var m = now.getMinutes();
    var s = now.getSeconds();
    if (h < 10) h = "0" + h;
    if (m < 10) m = "0" + m;
    if (s < 10) s = "0" + s;
    time.innerHTML = h + ":" + m + ":" + s;
  }
  updateSubClock();
  setInterval(updateSubClock, 500);
})();
